KG42.register("rules-52b6ec0d41d2c8a3c8dc418a",{"id":"06-sdr_energy_sharing::v141-c-R008","paper":"06-sdr_energy_sharing","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"The ESP is responsible for assuring payment balance in the energy-sharing zone. Scope: Payment balance within the microgrid energy-sharing zone. The ESP is responsible for charging participating prosumers a service fee for energy sharing. Scope: Service fees charged to participating PV prosumers for energy sharing. The applicable internal price enters the monetary electricity cost or income as the price multiplied by adjusted consumption minus PV production. Scope: The monetary electricity-cost or income component of a PV prosumer's net energy exchange at time slot h. The service fee is directly proportional to the amount of shared local PV energy. Scope: The ESP's aggregate service fee for PV energy sharing within the microgrid. Each prosumer's service-fee share is allocated according to its contribution of shared local energy. Scope: Allocation of individual service-fee shares among participating PV prosumers. The service fee should cover sharing-power losses and other possible expenditures for organizing sharing activities. Scope: Setting the service-fee level for the energy-sharing zone.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator","pricing.local","product.local_energy","settlement.payment"],"E":[{"edge_id":"v141-c-R008-E001","source":"coordination.local_operator","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R008-C001","v141-c-R008-C002"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e05","v141-b-g02-E-19"]},{"edge_id":"v141-c-R008-E002","source":"pricing.local","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R008-C003"],"evidence_ids":["v141-b-g01-e22","v141-b-g01-e23"]},{"edge_id":"v141-c-R008-E003","source":"product.local_energy","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R008-C004","v141-c-R008-C005"],"evidence_ids":["v141-b-g02-E-19","v141-b-g02-E-20"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Allocation of individual service-fee shares among participating PV prosumers. | Payment balance within the microgrid energy-sharing zone. | Service fees charged to participating PV prosumers for energy sharing. | Setting the service-fee level for the energy-sharing zone. | The ESP's aggregate service fee for PV energy sharing within the microgrid. | The monetary electricity-cost or income component of a PV prosumer's net energy exchange at time slot h.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e05","v141-b-g01-e22","v141-b-g01-e23","v141-b-g02-E-19","v141-b-g02-E-20","v141-b-g02-E-39"]},"x":[],"theta":[{"parameter_id":"v141-c-R008-theta-beta","symbol":"\\beta","meaning":"Charged percentage of shared energy, i.e. the service-fee rate applied to the actually shared (matched) local PV energy in the ESP's aggregate service income.","value":{"kind":"symbolic","number_value":null,"text_value":"β"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E-19","v141-b-g01-e02","v141-b-g02-E-39"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"procedural","role":"core","statement":"The ESP is responsible for assuring payment balance in the energy-sharing zone. Scope: Payment balance within the microgrid energy-sharing zone.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"]},{"constraint_id":"v141-c-R008-C002","kind":"procedural","role":"core","statement":"The ESP is responsible for charging participating prosumers a service fee for energy sharing. Scope: Service fees charged to participating PV prosumers for energy sharing.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e05","v141-b-g02-E-19"]},{"constraint_id":"v141-c-R008-C003","kind":"mathematical","role":"core","statement":"The applicable internal price enters the monetary electricity cost or income as the price multiplied by adjusted consumption minus PV production. Scope: The monetary electricity-cost or income component of a PV prosumer's net energy exchange at time slot h.","expression":"Pr_i^{h} \\left( x_i^{h} - P_i^{h} \\right)","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e22","v141-b-g01-e23"]},{"constraint_id":"v141-c-R008-C004","kind":"mathematical","role":"core","statement":"The service fee is directly proportional to the amount of shared local PV energy. Scope: The ESP's aggregate service fee for PV energy sharing within the microgrid.","expression":"S = \\beta \\sum_{h=1}^{H} \\min \\left( TSP^{h}, TBP^{h} \\right)","formalization_origin":"source","template_id":null,"members":["product.local_energy","settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R008-theta-beta"],"evidence_ids":["v141-b-g02-E-19"]},{"constraint_id":"v141-c-R008-C005","kind":"mathematical","role":"core","statement":"Each prosumer's service-fee share is allocated according to its contribution of shared local energy. Scope: Allocation of individual service-fee shares among participating PV prosumers.","expression":"S_{i}^{h} = \\frac{\\beta \\cdot \\left| NP_{i}^{h} \\right| \\cdot \\min \\left( TSP^{h}, TBP^{h} \\right)}{TSP^{h} + TBP^{h}}","formalization_origin":"source","template_id":null,"members":["product.local_energy","settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R008-theta-beta"],"evidence_ids":["v141-b-g02-E-20"]},{"constraint_id":"v141-c-R008-C006","kind":"procedural","role":"core","statement":"The service fee should cover sharing-power losses and other possible expenditures for organizing sharing activities. Scope: Setting the service-fee level for the energy-sharing zone.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R008-theta-beta"],"evidence_ids":["v141-b-g02-E-39"]},{"constraint_id":"v141-c-R008-C007","kind":"mathematical","role":"supporting","statement":"For 0 ≤ SDR ≤ 1, the energy-sharing zone's economic-balance condition equates total buying payments with internal selling receipts plus the ESP's utility-grid purchase cost of the residual: TBP·Pr_buy = TSP·Pr_sell + (TBP−TSP)λ^buy.","expression":"TBP \\cdot Pr_{buy} = TSP \\cdot Pr_{sell} + (TBP - TSP)\\lambda^{buy}, \\quad 0 \\leq SDR \\leq 1","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-e04","v141-b-g03-E18"]}],"pi":[{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-0812c00672-p03-c2r1__v141-a-M01-participation","page":3,"printed_page":"3571","section":"II. ENERGY SHARING STRUCTURE OF PV PROSUMERS / B. Energy Sharing Structure","anchor_text":"NSE FOR MICROGRIDS OF PEER-TO-PEER PROSUMERS 3571 In order to facilitate the organization of energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In order to facilitate the organization of energy sharing, a coordinator is required. Here, we introduce a new entity named Energy Sharing Provider (ESP). Generally, the ESP may belong to the microgrid operator or an independent third party company that focuses on the business mode of energy sharing, which provides energy sharing service for all participated PV prosumers. The ESP acts as an agent for prosumers and is responsible for assuring the power balance and the payment balance in the energy sharing zone. In this regard, the ESP is in charge of purchasing electricity from the utility grid, or from the PV prosumers with extra net power export, then selling electricity to other prosumers or the utility grid."},{"evidence_id":"v141-b-g01-e05","location":{"location_id":"src-0812c00672-p03-c2r2__v141-a-M01-participation","page":3,"printed_page":"3571","section":"II. ENERGY SHARING STRUCTURE OF PV PROSUMERS / B. Energy Sharing Structure","anchor_text":"charge of purchasing electricity from the utility grid, or from the PV prosumers with extra net powe","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"In the energy sharing zone, self-consumption of PV energy is still the first choice for PV prosumers. If PV energy can not satisfy the load demand, the PV prosumer would purchase energy agented by the ESP. If the demand of the PV prosumer is less than the production of PV source, the redundant PV power will be shared with other PV prosumers or sold to the utility grid via the ESP. In order to keep the fairness of energy sharing, the ESP should not have an optimal objective with any tendency, but it still needs to charge for service fee with the prosumers, as to cover the power losses and other possible expenditures."},{"evidence_id":"v141-b-g01-e22","location":{"location_id":"src-0812c00672-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":"3573","section":"III. ENERGY SHARING MODEL / C. Cost Model of the PV Prosumer","anchor_text":"h=1 where inci is the equivalent inconvenience cost of PV prosumer i, αi is the sensitivity coefﬁcie","equation_id":"(14),(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Integrating the inconvenience cost with the electricity cost or income of the PV prosumer, the cost function for optimal operation of PV prosumers can be defined as: C_i^{h}(x_i^{h}) = Pr_i^{h}(x_i^{h} - P_i^{h}) + \\alpha_i(x_i^{h} - TP_i^{h})^{2}   (14) ; C_i = \\sum_{h=1}^{H} C_i^{h}(x_i^{h})   (15) where C_i^{h}(x_i^{h}) can be separated into two parts: cost for using electricity Pr_i^{h}(x_i^{h} - P_i^{h}) and equivalent cost for adjusting flexible power \\alpha_i(x_i^{h} - TP_i^{h})^{2}. These two parts constitute the cost function in both economy and users' willingness."},{"evidence_id":"v141-b-g01-e23","location":{"location_id":"src-0812c00672-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":"3573","section":"III. ENERGY SHARING MODEL / C. Cost Model of the PV Prosumer","anchor_text":"where Chi (xhi ) can be separated into two parts: cost for using electricity Prhi (xhi −P ih ) and e","equation_id":"(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Pr_i^{h} is the price at time slot h for prosumer i, which can be selling price or buying price, and decided by the net power: Pr_i^{h} = f(NP_i^{h}) = \\begin{cases} Pr_{sell}^{h}, & NP_i^{h} \u003c 0 \\\\ Pr_{buy}^{h}, & NP_i^{h} \\geq 0 \\end{cases}   (16)"},{"evidence_id":"v141-b-g02-E-19","location":{"location_id":"src-0812c00672-p06-c1r3__v141-a-M01-pricing","page":6,"printed_page":null,"section":"D. Income Model of the ESP","anchor_text":"tr ri D. Income Model of the ESP pr As the agent of PV energy sharing, the ESP could charge the w se","equation_id":"(20)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"As the agent of PV energy sharing, the ESP could charge the service fee from the participating prosumers, which is directly proportional to the amount of shared PV energy. The income of the ESP in an operation day is deﬁned:\nS = \\beta \\sum_{h=1}^{H} \\min \\left( TSP^{h}, TBP^{h} \\right) \\quad (20)\nwhere \\beta is the charged percentage of shared energy."},{"evidence_id":"v141-b-g02-E-20","location":{"location_id":"src-0812c00672-p06-c1r3__v141-a-M01-pricing","page":6,"printed_page":null,"section":"D. Income Model of the ESP","anchor_text":"tr ri D. Income Model of the ESP pr As the agent of PV energy sharing, the ESP could charge the w se","equation_id":"(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"First, we think it is fair for all the prosumers to pay for the service fees according to their contributions of shared energy. The service fee distribution model can be formulated as:\nS_{i}^{h} = \\frac{\\beta \\cdot \\left| NP_{i}^{h} \\right| \\cdot \\min \\left( TSP^{h}, TBP^{h} \\right)}{TSP^{h} + TBP^{h}} \\quad (21)"},{"evidence_id":"v141-b-g02-E-39","location":{"location_id":"src-0812c00672-p06-c1r4__v141-a-M01-coordination","page":6,"printed_page":null,"section":"D. Income Model of the ESP","anchor_text":"t β · NP ih · min TSP h, TBP h (21) Shi = TSP h + TBP h ⎨ Moreover, for the value of β, the service ","equation_id":"(20)-(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Moreover, for the value of \\beta, the service fee should cover the losses of sharing power and other possible expenditures for organizing the sharing activities. In fact, the ESP is a virtual entity that cannot produce any PV energy, and thus the proﬁt should be limited for actual applications."},{"evidence_id":"v141-b-g01-e02","location":{"location_id":"src-0812c00672-p01-c2r2__v141-a-M01-pricing","page":1,"printed_page":"3569","section":"NOMENCLATURE","anchor_text":"ng S Income of the ESP in an operation day. re T P i Energy of original power consumption of PV pro-","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"NOMENCLATURE. B_m: Upper bound of PV energy feed in the utility grid. H: Total number of time slots in the operational time horizon. n: Total number of PV prosumers participant in the energy sharing zone. NP_i^h: Energy of net power of PV prosumer i in time slot h. NP_{i,ω}^h: Energy of net power of PV prosumer i in time slot h and scenario ω. P_i: PV energy of prosumer i in the operational time horizon. P_i^h: Produced PV energy of prosumer i in time slot h. Pr: Internal price set in the operational time horizon. Pr^h: Internal price in time slot h. Pr^{hω}: Internal price in time slot h and scenario ω. S: Income of the ESP in an operation day. TP_i: Energy of original power consumption of PV prosumer i in the operational time horizon. TP_i^h: Energy of the original power consumption of PV prosumer i in time slot h. TSP^h: Energy of total selling power in time slot h. TSP_ω^h: Energy of total selling power in time slot h and scenario ω. TBP^h: Energy of total buying power in time slot h. TBP_ω^h: Energy of total buying power in time slot h and scenario ω. TNP^h: Energy of total net power of the energy sharing zone in time slot h. SDR^h: SDR of the energy sharing zone in time slot h. SDR_ω^h: SDR of the energy sharing zone in time slot h and scenario ω. Pr_buy: Internal buying price of the energy sharing zone. Pr_sell: Internal selling price of the energy sharing zone. x_i: Adjusted power consumption profile of prosumer i in the operational time horizon. x_i^h: Adjusted power consumption of PV prosumer i in time slot h. inc_i: Equivalent cost of inconvenience of PV prosumer i. C_i^h(·): Cost function of PV prosumer i in time slot h. C_{i,ω}^h(·): Cost function of PV prosumer i in time slot h and scenario ω. α_i: Sensitivity coefficient of PV prosumer i. β: Percentage of service fee by shared energy. λ_buy: Unit price of buying energy from the utility grid. λ_sell: Unit price of selling energy to the utility grid. τ: Current time slot. δ_{i,ω}^h: Related error (%) of forecasted value of PV prosumer i in time slot h and scenario ω."},{"evidence_id":"v141-b-g03-E18","location":{"location_id":"src-0812c00672-p12-c1r3__v141-a-M01-pricing","page":12,"printed_page":"3580","section":"Appendix I","anchor_text":"TBP · Prbuy = TSP · Prsell + (TBP TSP) λ (31) By substituting (7) into (31), there is: TBP · Prbuy =","equation_id":"(31), (32), (33), (34)","figure_id":null,"table_id":null,"image_ref":"pages/page-12.png","occurrence_role":"formula"},"source_text":"Considering the economical balance requirement of the energy sharing zone, we can further deduce the internal buying price Pr^{h}_{buy} based on the internal selling price Pr^{h}_{sell}. If 0 ≤ SDR ≤ 1, since the ESP need to purchase energy from the utility grid, the economic balance can be described as: TBP · Pr_{buy} = TSP · Pr_{sell} + (TBP − TSP) λ^{buy} (31). By substituting (7) into (31), there is: TBP · Pr_{buy} = TBP · SDR · Pr_{sell} + (TBP − TBP · SDR) λ^{buy} (32). Thus, we can deduce the Pr_{buy} as: Pr_{buy} = SDR · Pr_{sell} + (1 − SDR) λ^{buy} (33). Otherwise, if SDR > 1, similar with the condition of internal selling price, the internal buying price is: Pr_{buy} = λ^{sell} (34)."},{"evidence_id":"v141-b-g04-e04","location":{"location_id":"src-0812c00672-p12-c1r2__v141-a-M01-pricing","page":12,"printed_page":null,"section":null,"anchor_text":"a = λbλbuuy y−λsλs e ellll (29) b = λb1u y w Finally, by substituting (29) into (28), the function o","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-12.png","occurrence_role":"formula"},"source_text":"(31) TBP\\cdot Pr_{buy}=TSP\\cdot Pr_{sell}+(TBP-TSP)\\lambda^{buy}"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"The formalized payment term uses x_i^h as the prosumer's adjusted power-consumption input, but x_i^h is defined and decided in the scheduling/clearing rule (v141-a-M01-clearing). R008's frozen V (coordination.local_operator, pricing.local, product.local_energy, settlement.payment) has no clearing/decision node, so declaring x_i^h as an R008 x object would cross rule scope; it remains a source symbol inside C003 with its scheduling scope.","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e03","quote":"The ESP acts as an agent for prosumers and is responsible for assuring the power balance and the payment balance in the energy sharing zone."}],[{"evidence_id":"v141-b-g01-e05","quote":"In order to keep the fairness of energy sharing, the ESP should not have an optimal objective with any tendency, but it still needs to charge for service fee with the prosumers, as to cover the power losses and other possible expenditures."},{"evidence_id":"v141-b-g02-E-19","quote":"the ESP could charge the service fee from the participating prosumers"}],[{"evidence_id":"v141-b-g01-e22","quote":"where C_i^{h}(x_i^{h}) can be separated into two parts: cost for using electricity Pr_i^{h}(x_i^{h} - P_i^{h})"},{"evidence_id":"v141-b-g01-e23","quote":"Pr_i^{h} is the price at time slot h for prosumer i, which can be selling price or buying price, and decided by the net power:"}],[{"evidence_id":"v141-b-g02-E-19","quote":"As the agent of PV energy sharing, the ESP could charge the service fee from the participating prosumers, which is directly proportional to the amount of shared PV energy."}],[{"evidence_id":"v141-b-g02-E-20","quote":"First, we think it is fair for all the prosumers to pay for the service fees according to their contributions of shared energy. The service fee distribution model can be formulated as:"}],[{"evidence_id":"v141-b-g02-E-39","quote":"the service fee should cover the losses of sharing power and other possible expenditures for organizing the sharing activities."}]],"C2_formalization":{"graph_sha256":"dc0108109bdfab47245c5c5602599bffb6aea88abb74b8b3faa31e3b5a78147c","applicability":"formalized","reason":"The frozen R008 payment rule supports source-grounded expressions for the internal-price monetary electricity-cost/income term (Eq. 14 first term), the ESP aggregate service-fee income (Eq. 20), the individual service-fee allocation (Eq. 21), and the zone economic/payment-balance identity (Eq. 31). C001, C002, and C006 remain procedural/condition statements because the supplied evidence does not provide a fully specified mathematical formula for the ESP payment-balance responsibility itself, the charging action, or the fee-cover condition; C006 in particular lacks a defined loss/expenditure term.","bindings":[{"object_id":"v141-c-R008-theta-beta","node_ids":["settlement.payment","coordination.local_operator"],"edge_ids":["v141-c-R008-E001"],"rationale":"β is the charged percentage of shared energy in the ESP's service-fee formula; it parameterizes the frozen coordination.local_operator→settlement.payment edge E001."},{"object_id":"v141-c-R008-C003","node_ids":["pricing.local","settlement.payment"],"edge_ids":["v141-c-R008-E002"],"rationale":"C003's monetary electricity-cost/income term Pr_i^h(x_i^h−P_i^h) is the payment consequence of the internal price; E002 is the frozen pricing.local→settlement.payment link assigned to C003."},{"object_id":"v141-c-R008-C004","node_ids":["product.local_energy","settlement.payment"],"edge_ids":["v141-c-R008-E003"],"rationale":"C004 defines the ESP aggregate service fee as directly proportional to shared local PV energy; E003 is the frozen product.local_energy→settlement.payment link assigned to C004/C005."},{"object_id":"v141-c-R008-C005","node_ids":["product.local_energy","settlement.payment"],"edge_ids":["v141-c-R008-E003"],"rationale":"C005 allocates individual service-fee shares according to each prosumer's contribution to shared local energy, the same frozen product.local_energy→settlement.payment link."},{"object_id":"v141-c-R008-C007","node_ids":["coordination.local_operator","pricing.local","settlement.payment"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"C007's economic-balance identity couples internal buying/selling prices to settlement and expresses the ESP's payment-balance responsibility; E001 and E002 are the frozen links into settlement.payment."}],"revision_requests":["C006: the supplied source condition that the service fee should cover sharing-power losses and other expenditures has no defined loss/expenditure term; formalization remains not_formalized without a B re-extraction of that term.","C003 uses x_i^h (adjusted prosumer consumption) owned by the clearing/scheduling rule; R008's frozen V lacks a clearing node, so x_i^h is kept as a source symbol rather than declared as R008's x."]}},"quarantined_references":[]}});
